// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller, address candidateNewOwner) public {
        vm.assume(caller != address(0));
        vm.assume(candidateNewOwner != address(0));

        address initialOwner = address(this);
        address ownerBefore = c.owner();

        bool ok;
        vm.prank(caller);
        try c.transferOwnership(candidateNewOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        address ownerAfter = c.owner();

        if (caller != ownerBefore) {
            assertTrue(ownerAfter == ownerBefore);
        } else {
            assertTrue(c.owner() == ownerAfter);
        }
    }
}
